-- ===========================================================================
-- 07_seed_contas.sql — Empresas do grupo e suas contas bancárias
--
-- GERADO AUTOMATICAMENTE. Não edite à mão: rode o importador de novo.
--   Origem : Mapeamento_Geral_de_Contas_2023_Equipe.xlsx
--   Aba    : BASE GERAL
--   Quando : 2026-08-06T12:03:13.584Z
--   Contém : 213 empresas, 1127 contas (1073 ativas, 54 encerradas)
--
-- Estratégia de recarga: marcamos TUDO como inativo, depois reativamos o que
-- veio na planilha. Nada é apagado, para os boletos antigos continuarem
-- fazendo sentido mesmo que a empresa saia da planilha.
-- ===========================================================================

begin;

update public.empresas set ativo = false;
update public.contas_bancarias set ativo = false;

-- --------------------------------------------------------------- EMPRESAS --
on conflict (documento) do update set
  documento_tipo       = excluded.documento_tipo,
  razao_social         = excluded.razao_social,
  razao_social_juridica = excluded.razao_social_juridica,
  nomes_alternativos = excluded.nomes_alternativos,
  chave_busca        = excluded.chave_busca,
  grupo_economico    = excluded.grupo_economico,
  codigo_interno     = excluded.codigo_interno,
  ativo              = true;

-- ------------------------------------------------------ CONTAS BANCÁRIAS --
on conflict (empresa_documento, conta) do update set
  conta_digitos = excluded.conta_digitos,
  banco         = excluded.banco,
  cod_banco     = excluded.cod_banco,
  agencia       = excluded.agencia,
  tipo_conta    = excluded.tipo_conta,
  ativo         = excluded.ativo;

on conflict (empresa_documento, conta) do update set
  conta_digitos = excluded.conta_digitos,
  banco         = excluded.banco,
  cod_banco     = excluded.cod_banco,
  agencia       = excluded.agencia,
  tipo_conta    = excluded.tipo_conta,
  ativo         = excluded.ativo;

on conflict (empresa_documento, conta) do update set
  conta_digitos = excluded.conta_digitos,
  banco         = excluded.banco,
  cod_banco     = excluded.cod_banco,
  agencia       = excluded.agencia,
  tipo_conta    = excluded.tipo_conta,
  ativo         = excluded.ativo;

commit;

